def transform(grid):
    h, w = len(grid), len(grid[0])
    # Complete horizontal bands by finding the shortest row-index period
    # consistent with every nonblank uniform row.
    bands = {}
    horizontal = True
    for r, row in enumerate(grid):
        nz = [v for v in row if v != 0]
        if nz:
            if len(nz) != w or len(set(nz)) != 1:
                horizontal = False
                break
            bands[r] = nz[0]
    if horizontal and bands:
        p = next(p for p in range(1, h + 1)
                 if all((a-b) % p != 0 or va == vb
                        for a, va in bands.items()
                        for b, vb in bands.items()))
        phase = {r % p: v for r, v in bands.items()}
        fallback = next(iter(bands.values()))
        for k in range(p):
            phase.setdefault(k, fallback)
        return [[phase[r % p]] * w for r in range(h)]

    # Sparse diagonal clue grids specify a repeating color by r+c phase.
    pts = [(r, c, v) for r, row in enumerate(grid)
           for c, v in enumerate(row) if v]
    p = next(p for p in range(1, max(h, w) + 1)
             if all((r1+c1-r2-c2) % p != 0 or v1 == v2
                    for i, (r1,c1,v1) in enumerate(pts)
                    for r2,c2,v2 in pts[i+1:]))
    phase = {(r+c) % p: v for r,c,v in pts}
    fallback = next(iter(phase.values()))
    for k in range(p):
        phase.setdefault(k, fallback)
    return [[phase[(r+c) % p] for c in range(w)] for r in range(h)]

